import{_ as a,o as e,c as r,a0 as o}from"./chunks/framework.DqMqoJl9.js";const u=JSON.parse('{"title":"单人全栈做帧间：两台服务器怎么分工","description":"","frontmatter":{"title":"单人全栈做帧间：两台服务器怎么分工","date":"2026-10-02T00:00:00.000Z","tags":["架构","部署","成本控制","独立开发"]},"headers":[],"relativePath":"posts/two-servers.md","filePath":"posts/two-servers.md","lastUpdated":null}'),l={name:"posts/two-servers.md"};function s(d,t,i,n,h,p){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="单人全栈做帧间-两台服务器怎么分工" tabindex="-1">单人全栈做帧间：两台服务器怎么分工 <a class="header-anchor" href="#单人全栈做帧间-两台服务器怎么分工" aria-label="Permalink to &quot;单人全栈做帧间：两台服务器怎么分工&quot;">​</a></h1><p>单人开发不代表只用一台机器。帧间有两类截然不同的算力需求，硬塞一台机器会互相拖垮，分开部署各自跑满。</p><h2 id="两类负载的差异" tabindex="-1">两类负载的差异 <a class="header-anchor" href="#两类负载的差异" aria-label="Permalink to &quot;两类负载的差异&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>采源拆解机</th><th>生成服务机</th></tr></thead><tbody><tr><td>任务</td><td>视频下载、抽帧、Whisper 转写、视觉特征提取</td><td>LLM 拆解成稿、创作台推理</td></tr><tr><td>特点</td><td>IO 密集 + 视觉特征计算</td><td>显存/推理密集</td></tr><tr><td>配置</td><td>i7-12700KF + RTX 4070 12GB</td><td>A10 24GB + 64GB 内存</td></tr></tbody></table><p>拆解管线要在 3~180 秒的视频里按 0.5~1 秒间隔截取关键帧（最多 180 张），跑转写、提特征——这活吃 CPU/IO 和显存带宽，但模型不大。生成服务跑的是大语言模型推理，瓶颈在显存容量和显存带宽。</p><h2 id="为什么-llm-放本地" tabindex="-1">为什么 LLM 放本地 <a class="header-anchor" href="#为什么-llm-放本地" aria-label="Permalink to &quot;为什么 LLM 放本地&quot;">​</a></h2><p>帧间选择 Ollama 部署 Qwen 系列模型在本地生成机上跑，理由很实际：</p><ol><li><strong>按次计费的产品，边际成本是命</strong>。云端按 token 收费，用户拆一个视频就是几十上百次调用，量起来账单会吃掉毛利；本地推理只有电费</li><li><strong>数据不出服务器</strong>。MCN 客户的内容资产留在自己的机器上，少了合规和信任的麻烦</li><li><strong>离线可用</strong>。云端抽风/限流时本地模型兜底，链路不中断</li></ol><h2 id="云端也没有完全退出" tabindex="-1">云端也没有完全退出 <a class="header-anchor" href="#云端也没有完全退出" aria-label="Permalink to &quot;云端也没有完全退出&quot;">​</a></h2><p>纯本地会被模型能力天花板卡住：本地 8B/14B 模型的质量拼不过云端旗舰。所以架构是<strong>本地兜底 + 云端提优</strong>：</p><ul><li>默认档位走免费/低价云端模型（glm-4-flash 等），成本可控</li><li>成稿这类质量敏感环节可以路由到本地 qwen3.5（慢但稳）</li><li>复杂任务按需切到云端 pro 档</li></ul><p>选哪条路，由统一网关按&quot;质量 × 成本 × 可用性&quot;决定，业务代码无感知。</p><h2 id="单人运维的取舍" tabindex="-1">单人运维的取舍 <a class="header-anchor" href="#单人运维的取舍" aria-label="Permalink to &quot;单人运维的取舍&quot;">​</a></h2><p>双服务器意味着双份运维：监控、升级、备份。作为单人项目，我的原则是<strong>能自动化的绝不手工</strong>：定时任务、健康检查、一键部署脚本，都是为&quot;一个人管两台机器&quot;服务的。</p><blockquote><p>面试追问点：你怎么决定一个推理任务走本地还是云端？——答档位路由 + 质量/成本契约，而不是写死在代码里。</p></blockquote>',15)])])}const _=a(l,[["render",s]]);export{u as __pageData,_ as default};
